#!/usr/bin/env python3
"""Generate port/src/states_data.js from id's source (behaviour tables only): sprite enum numbers (WL_DEF.H) and the statetype tables of WL_ACT2.C
for guard, officer, SS, mutant, dog and the shared dead states. Entries: name -> [rotate, sprite number, tics, think, action, next]."""
import json, os, re
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); S = f"{R}/vendor/wolf3d_src/WOLFSRC"
rd = lambda f: open(f"{S}/{f}", "rb").read().decode("latin1").replace("\r", "")
def strip_cond(t):   # WL6 branch: keep #ifndef SPEAR bodies, drop #ifdef SPEAR / #else of ifndef
    out, stack = [], []
    for l in t.split("\n"):
        s = l.strip()
        if s.startswith("#ifdef SPEAR") or s.startswith("#if 0"): stack.append(False); continue
        if s.startswith("#if"): stack.append(True); continue
        if s.startswith("#else"): stack[-1] = not stack[-1]; continue
        if s.startswith("#endif"): stack.pop(); continue
        if s.startswith("#"): continue
        if all(stack): out.append(l)
    return "\n".join(out)
d = rd("WL_DEF.H"); i = d.index("SPR_DEMO,"); j = re.compile(r"\}\s*;").search(d, i).end(); body = strip_cond(d[d.rindex("enum", 0, i):j])
body = re.sub(r"/\*.*?\*/", "", body, flags=re.S); body = re.sub(r"//[^\n]*", "", body)
names = re.findall(r"\w+", body[body.index("{") + 1:]); spr = {n: k for k, n in enumerate(names)}
a = strip_cond(rd("WL_ACT2.C")); st = {}
for m in re.finditer(r"statetype\s+(s_\w+)\s*=\s*\{([^}]*)\}", a):
    f = [x.strip() for x in m.group(2).split(",")]
    if len(f) != 6: continue
    rot = {"true": 1, "false": 0}.get(f[0], f[0]); sp = spr.get(f[1], f[1] if f[1].isdigit() else None)
    if sp is None: continue
    st[m.group(1)] = [int(rot), sp, int(f[2]), None if f[3] == "NULL" else f[3], None if f[4] == "NULL" else f[4], None if f[5] == "NULL" else f[5].lstrip("&")]
ia = rd("WL_INTER.C"); pt = ia[ia.index("times parTimes[]"):]; pt = pt[:pt.index("};")]; pt = strip_cond(pt)
par = [float(x) for x in re.findall(r"\{\s*([0-9.]+)\s*,\s*\"[0-9?:]+\"\s*\}", pt)]
keep = {k: v for k, v in st.items() if re.match(r"s_(grd|ofc|ss|mut|dog|boss|bj|gretel|schabb|gift|fat|fake|mecha|hitler|needle|fire|rocket|smoke|boom)", k)}
open(f"{R}/port/src/states_data.js", "w").write("// generated by scripts/gen_states.py from id's source (WL_ACT2.C statetype tables): name -> [rotate, sprite, tics, think, action, next]\nexport const STATES = " + json.dumps(keep, indent=0) + ";\nexport const PAR = " + json.dumps(par) + ";   // par time in minutes per level (episode*10 + map)\nexport const SPR = " + json.dumps({k: spr[k] for k in ('SPR_KNIFEREADY', 'SPR_PISTOLREADY', 'SPR_MACHINEGUNREADY', 'SPR_CHAINREADY', 'SPR_STAT_0')}) + ";\n")
print(len(names), "sprites,", len(keep), "states")
# pic chunk numbers (GFXV_WL6.H): count the enumerators from H_BJPIC=3 (the // comments in the header are not reliable)
gh = rd("GFXV_WL6.H"); pics = {}; n = None
for l in gh.split("\n"):
    l = re.sub(r"//.*", "", l).strip().rstrip(",")
    if not re.match(r"^\w+(=\d+)?$", l): continue
    m = re.match(r"^(\w+)=(\d+)$", l); name, n = (m.group(1), int(m.group(2))) if m else (l, None if n is None else n + 1)
    if name.endswith("PIC"): pics[name] = n
    if m is None and n is None: continue
# our VGAGRAPH has 144 pics, the source header 132: from STATUSBARPIC on every chunk is 12 higher (found by pic sizes: STATUSBARPIC 320x40 at 98, TITLEPIC 320x200 at 99,
# weapon icons 48x24, numbers 8x16, faces 24x32); names before it cannot be mapped this way
SHIFT = 12
pics = {k: (v + SHIFT if v >= pics["C_OPTIONSPIC"] else v) for k, v in pics.items()}   # menu pics (C_OPTIONSPIC on) are shifted too: Options banner 152x48 is chunk 22, found with port/sheet_png.mjs; the H_* help pics before it do not map
open(f"{R}/port/src/gfx_names.js", "w").write("// generated by scripts/gen_states.py from GFXV_WL6.H: pic name -> VGAGRAPH chunk number (names from STATUSBARPIC on are shifted by 12 for this data, names before it are NOT reliable)\nexport const PIC = " + json.dumps(pics) + ";\nexport const STARTPICS = 3, NUMPICS = 144;\n")
# sound names (AUDIOWL6.H enum order = sound number; adlib chunk = 87 + n in AUDIOT) and the WL6 digitized map (WL_MAIN.C wolfdigimap: sound name -> digi slot in VSWAP)
ah_full = rd("AUDIOWL6.H"); ah = ah_full[ah_full.index("typedef enum"):]; ah = ah[:ah.index("}")]
snd = {n: i for i, n in enumerate(re.findall(r"(\w+SND)\s*,", re.sub(r"//[^\n]*", "", ah)))}
wm = rd("WL_MAIN.C"); wm = wm[wm.index("wolfdigimap[]"):]; wm = wm[:wm.index("#else")]
digi = {n: int(v) for n, v in re.findall(r"(\w+SND)\s*,\s*(\d+)", wm)}
mus = {n: i for i, n in enumerate(re.findall(r"(\w+_MUS)\s*,", re.sub(r"//[^\n]*", "", ah_full[ah_full.index("CORNER_MUS"):])))}
import struct   # the per-level song table is not in the released source (StartMusic is missing): read it from the original exe, 60 u16 song numbers, E1M1 = GETTHEM(3) SEARCHN(11) POW(9) SUSPENSE(12)...
exe = open(f"{R}/vendor/ref/WOLF3D.EXE", "rb").read(); at = exe.find(struct.pack("<10H", 3, 11, 9, 12, 3, 11, 9, 12, 2, 0)); songs = list(struct.unpack("<60H", exe[at:at + 120]))
ah_ = open(f"{R}/vendor/ref/AUDIOHED.WL6", "rb").read(); at_ = open(f"{R}/vendor/ref/AUDIOT.WL6", "rb").read()
sndinfo = {}   # name -> [priority, PC speaker length in 140 Hz ticks]: SD_PlaySound's priority rule and how long SD_SoundPlaying reports the sound. The PC speaker chunk (0..86) is used because the harness
for n, i in snd.items():   # runs DOSBox without a sound card, so the original is in PC speaker mode (found by the chaingun pickup: 95 ticks = 47 tics, the 47 frames where UpdateFace drew no random numbers)
    a0, a1 = struct.unpack_from("<II", ah_, i * 4)
    if a1 - a0 >= 6: sndinfo[n] = [struct.unpack_from("<H", at_, a0 + 4)[0], struct.unpack_from("<I", at_, a0)[0]]
open(f"{R}/port/src/sound_data.js", "w").write("// generated by scripts/gen_states.py: sound name -> number (adlib chunk 87 + n in AUDIOT.WL6), name -> digitized slot in VSWAP.WL6 (WL6 branch of WL_MAIN.C wolfdigimap),\n// music name -> song number (AUDIOT chunk 261 + n), LEVELSONGS = song per level (episode*10 + map) read from WOLF3D.EXE\nexport const SND = " + json.dumps(snd) + ";\nexport const DIGI = " + json.dumps(digi) + ";\nexport const MUS = " + json.dumps(mus) + ";\nexport const LEVELSONGS = " + json.dumps(songs) + ";\nexport const SNDINFO = " + json.dumps(sndinfo) + ";\n")
print(len(snd), "sounds,", len(digi), "digitized")
